def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    op = [h[1] for h in history]
    my = [h[0] for h in history]

    # Opponent cooperation statistics
    op_c = 0
    for a in op:
        if a == 'C':
            op_c += 1
    op_d = n - op_c
    op_rate = op_c / n

    recent_len = 10 if n >= 10 else n
    recent_op = op[-recent_len:]
    recent_c = 0
    recent_d = 0
    for a in recent_op:
        if a == 'C':
            recent_c += 1
        else:
            recent_d += 1

    last_op = op[-1]
    last_me = my[-1]

    # Current defection streak of opponent
    def_streak = 0
    i = n - 1
    while i >= 0 and op[i] == 'D':
        def_streak += 1
        i -= 1

    # Current cooperation streak of opponent
    coop_streak = 0
    i = n - 1
    while i >= 0 and op[i] == 'C':
        coop_streak += 1
        i -= 1

    # Our defection streak
    my_def_streak = 0
    i = n - 1
    while i >= 0 and my[i] == 'D':
        my_def_streak += 1
        i -= 1

    # Very end of match: clean exploitation of cooperators
    if n >= 99:
        if last_op == 'C':
            return 'D'
        return 'D'

    # Near end: exploit if opponent likely to cooperate
    if n >= 96:
        if recent_c >= 4 and op_rate > 0.5:
            return 'D'
        if last_op == 'C' and op_rate > 0.6:
            return 'D'
        if def_streak >= 3:
            return 'D'
        if last_op == 'C':
            return 'C'
        return 'D'

    # If opponent almost never defects, cooperate but test soon.
    if op_d == 0:
        # Test occasionally, but mostly keep mutual cooperation.
        if n >= 15 and n % 13 == 0 and rng.random() < 0.35:
            return 'D'
        return 'C'

    # If opponent is a relentless defector, defect almost always.
    if op_rate <= 0.15:
        if rng.random() < 0.07:
            return 'C'
        return 'D'

    # Mostly defective but not completely: defect, with rare probes.
    if op_rate <= 0.35:
        if rng.random() < 0.12:
            return 'C'
        return 'D'

    # Recovery after our own long defection: return to cooperation quickly to
    # avoid getting locked into mutual defection.
    if my_def_streak >= 3 and op_rate > 0.5:
        return 'C'

    # If opponent is in a long cooperation streak, cooperate, with rare probes.
    if coop_streak >= 8 and op_rate > 0.65:
        if n < 90 and rng.random() < 0.08:
            return 'D'
        return 'C'

    # If opponent just defected:
    if last_op == 'D':
        # If this looks like an isolated defection from generally cooperative
        # opponent, forgive sometimes to recover mutual cooperation.
        if def_streak == 1 and op_rate > 0.65:
            if rng.random() < 0.45:
                return 'C'
            return 'D'

        # If opponent has defected several times in recent window, retaliate.
        if recent_d >= 3:
            # But occasionally try to restart cooperation.
            if rng.random() < 0.10:
                return 'C'
            return 'D'

        # Moderate defection: retaliate but be open to forgiveness.
        if rng.random() < 0.75:
            return 'D'
        return 'C'

    # Opponent cooperated last round.
    # If generally cooperative, mostly cooperate; occasionally test for extra points.
    if op_rate >= 0.75:
        if n >= 20 and coop_streak >= 5 and n % 17 == 0 and rng.random() < 0.25:
            return 'D'
        return 'C'

    if op_rate >= 0.5:
        if recent_c >= 7 and n % 19 == 0 and rng.random() < 0.20:
            return 'D'
        return 'C'

    # Opponent is moderately defective but cooperated last round.
    # Punish occasionally but keep possibility of mutual cooperation.
    if recent_d >= 2:
        if rng.random() < 0.35:
            return 'D'
        return 'C'

    if rng.random() < 0.15:
        return 'D'
    return 'C'
